import{_ as t,o,c as a,a0 as i}from"./chunks/framework.BWpMpcZ2.js";const p=JSON.parse('{"title":"Debugging","description":"","frontmatter":{},"headers":[],"relativePath":"debugging.md","filePath":"debugging.md"}'),r={name:"debugging.md"};function n(s,e,l,d,c,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h1><p>margin logs every AI request and response locally so you can inspect what&#39;s happening under the hood.</p><h2 id="ai-logs" tabindex="-1">AI Logs <a class="header-anchor" href="#ai-logs" aria-label="Permalink to &quot;AI Logs&quot;">​</a></h2><p>Every time you send a request to the AI (in edit mode or chat mode), margin saves a log entry that includes:</p><ul><li>Your input prompt / instruction</li><li>The complete context sent to the writer agent (characters, styles, additional context, etc.)</li><li>The full AI response</li><li>Token usage information</li><li>Session ID and timestamp</li></ul><p>These logs are stored as JSON files in the <code>outputs/ai_logs/</code> folder inside your workspace.</p><h3 id="viewing-logs" tabindex="-1">Viewing Logs <a class="header-anchor" href="#viewing-logs" aria-label="Permalink to &quot;Viewing Logs&quot;">​</a></h3><p>You can view logs directly in the app through the <strong>AI Assist panel</strong> -- look for the log/book icon that opens the request inspector. This shows the last API request, the input and output context, the total session context, and remaining context window.</p><h3 id="editing-or-clearing-logs" tabindex="-1">Editing or Clearing Logs <a class="header-anchor" href="#editing-or-clearing-logs" aria-label="Permalink to &quot;Editing or Clearing Logs&quot;">​</a></h3><ul><li>Logs are plain JSON files -- you can open, edit, or delete them with any text editor.</li><li>To clear all logs for a session, use the delete option in the log viewer.</li></ul><div class="tip custom-block"><p class="custom-block-title">Logs are purely local. They never leave your machine.</p></div><h2 id="inspecting-prompts" tabindex="-1">Inspecting Prompts <a class="header-anchor" href="#inspecting-prompts" aria-label="Permalink to &quot;Inspecting Prompts&quot;">​</a></h2><p>The prompt templates used by the Planner and Writer agents are stored as markdown files in the <code>prompts/</code> folder at the project root:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>prompts/simple-planner.md</code></td><td>Instructions for the Planner agent</td></tr><tr><td><code>prompts/simple-writer.md</code></td><td>Instructions for the Writer agent</td></tr><tr><td><code>prompts/simple-chat.md</code></td><td>Instructions for Chat mode</td></tr></tbody></table><p>You can read these files to understand exactly what instructions are being sent to the AI. Edits take effect immediately -- no restart needed.</p><div class="warning custom-block"><p class="custom-block-title">Editing prompts changes how the AI behaves. If something breaks, you can restore the original from the project&#39;s git history.</p></div><h2 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to &quot;Telemetry&quot;">​</a></h2><p>margin has <strong>no external telemetry</strong>. There are no analytics, no tracking scripts, and no data sent to external servers (except the AI provider you explicitly configure).</p><p>The only &quot;telemetry&quot; is local:</p><ul><li><strong>AI logs</strong> stored in <code>outputs/ai_logs/</code> for debugging your own requests</li><li><strong>Settings</strong> saved in your platform&#39;s config directory — <code>~/.config/slm-writing-engine/settings.json</code> on Linux, <code>~/Library/Application Support/slm-writing-engine/settings.json</code> on macOS, <code>%APPDATA%\\slm-writing-engine\\settings.json</code> on Windows</li><li><strong>No crash reports, no usage stats, no pings home</strong></li></ul><p>Everything stays on your machine.</p><h2 id="image-issues" tabindex="-1">Image Issues <a class="header-anchor" href="#image-issues" aria-label="Permalink to &quot;Image Issues&quot;">​</a></h2><p>Images are plain Markdown references (<code>![alt](assets/foo.png)</code>), so most problems come down to a mismatch between the text and the file. Your Markdown is never auto-deleted or rewritten — fix the underlying cause and the image comes back.</p><h3 id="broken-image-placeholder" tabindex="-1">Broken image placeholder <a class="header-anchor" href="#broken-image-placeholder" aria-label="Permalink to &quot;Broken image placeholder&quot;">​</a></h3><p>The referenced asset file is missing — it was renamed, moved, or deleted. Check that the file exists under your workspace&#39;s <code>assets/</code> folder and that the path in the Markdown matches exactly (including case). Editing the source line to the correct path restores the image.</p><h3 id="pasted-image-doesn-t-appear" tabindex="-1">Pasted image doesn&#39;t appear <a class="header-anchor" href="#pasted-image-doesn-t-appear" aria-label="Permalink to &quot;Pasted image doesn&#39;t appear&quot;">​</a></h3><ul><li>If an upload alert appeared, the file wasn&#39;t a supported image (PNG, JPG, WebP, GIF) — the pasted text itself is untouched.</li><li>If a pasted image URL produced no image, the download failed (bad link, offline host, or a non-image response). Your pasted URL text stays in the document; try the URL in a browser to check it.</li></ul><h3 id="wrong-size-after-editing-dimensions" tabindex="-1">Wrong size after editing dimensions <a class="header-anchor" href="#wrong-size-after-editing-dimensions" aria-label="Permalink to &quot;Wrong size after editing dimensions&quot;">​</a></h3><p>Only positive integers count: <code>![alt|0](x.png)</code> or <code>![alt|-5](x.png)</code> fall back to natural size. A <code>|</code> followed by non-digits (e.g. <code>![a|b](x.png)</code>) is treated as literal alt text, not a size. An <code>{align=...}</code> value other than <code>left</code>, <code>center</code>, or <code>right</code> is left as visible text — correct the spelling to apply it.</p><h3 id="remote-image-never-becomes-local" tabindex="-1">Remote image never becomes local <a class="header-anchor" href="#remote-image-never-becomes-local" aria-label="Permalink to &quot;Remote image never becomes local&quot;">​</a></h3><p>Only explicitly pasted/imported image URLs are downloaded into <code>assets/</code>. An image URL you typed by hand into Markdown stays remote by design — paste the URL as document content if you want margin to import a local copy.</p><h3 id="image-looks-too-large-after-import" tabindex="-1">Image looks too large after import <a class="header-anchor" href="#image-looks-too-large-after-import" aria-label="Permalink to &quot;Image looks too large after import&quot;">​</a></h3><p>New images render at natural size bounded by the editor width. Select the image and drag a handle (or reset) to persist a smaller width.</p>',33)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
